    mov     d0, a3
    mov     d0, (0x5003a578)
    mov     a3, (0x5003a58c)
    mov     0xc, d0
    add     a3, d0
    mov     d0, (0x5003a5a0)
    mov     (FACTORY_DATA_FLASH), a0
    add     a2, a0
    cmp     0x57000200, a0
    beq     loc_48449F03
    jmp     loc_48449FD8
